<?php require __DIR__.'/_nav.php'; use OCP\IURLGenerator; $url=\OC::$server->get(IURLGenerator::class); $prev=date('Y-m-d',strtotime($_['weekStart'].' -7 days')); $next=date('Y-m-d',strtotime($_['weekStart'].' +7 days')); ?>
<div id="app-content"><div class="erp-page"><h1>Zeiterfassung</h1><p class="erp-sub">Zeit einmal erfassen und später direkt in den Rapport übernehmen. Manuell oder mit laufendem Projekt-Timer.</p>
