<form class="erp-form-card" method="post" action="<?php p($url->linkToRoute('reinhardterp.module.startTimer')); ?>"><input type="hidden" name="requesttoken" value="<?php p($requestToken); ?>"><div class="erp-form-grid"><div><label>Mitarbeiter / Monteur</label><select name="userId" required><option value="">Mitarbeiter wählen</option><?php foreach($_['users'] as $u): ?><option value="<?php p($u['uid']); ?>" <?=$u['uid']===$permissions->uid()?'selected':''?>><?php p($u['displayName'].' · '.$u['uid']); ?></option><?php endforeach; ?></select></div><div><label>Projekt</label><select name="projectId" required><option value="">Projekt wählen</option><?php foreach($_['projects'] as $p): ?><option value="<?php p($p['id']); ?>"><?php p($p['project_no'].' · '.$p['title']); ?></option><?php endforeach; ?></select></div><div class="erp-span-2"><label>Tätigkeit</label><textarea name="activity" rows="4" required placeholder="Was wird ausgeführt?"></textarea></div></div><button class="button primary">▶ Zeit starten</button></form>
<h2>Manuelle Zeiterfassung</h2>
<form class="erp-form-card" method="post" action="<?php p($url->linkToRoute('reinhardterp.module.saveWorkday')); ?>"><input type="hidden" name="requesttoken" value="<?php p($requestToken); ?>"><div class="erp-form-grid"><div><label>Mitarbeiter / Monteur</label><select name="userId" required><option value="">Mitarbeiter wählen</option><?php foreach($_['users'] as $u): ?><option value="<?php p($u['uid']); ?>" <?=$u['uid']===$permissions->uid()?'selected':''?>><?php p($u['displayName'].' · '.$u['uid']); ?></option><?php endforeach; ?></select></div><div><label>Datum</label><input type="date" name="workDate" value="<?php p(date('Y-m-d')); ?>" required></div><div><label>Projekt</label><select name="projectId" required><option value="">Projekt wählen</option><?php foreach($_['projects'] as $p): ?><option value="<?php p($p['id']); ?>"><?php p($p['project_no'].' · '.$p['title']); ?></option><?php endforeach; ?></select></div><div><label>Beginn</label><input type="time" name="startTime"></div><div><label>Ende</label><input type="time" name="endTime"></div><div><label>Pause in Minuten</label><input type="number" min="0" name="breakMinutes" value="0"></div><div><label>Stunden (alternativ)</label><input type="number" step="0.25" min="0" name="hours" value="0"><small>0 = automatische Berechnung.</small></div><div class="erp-span-2"><label>Tätigkeit</label><textarea name="activity" rows="10" required placeholder="Ausführlich beschreiben, was ausgeführt wurde …"></textarea></div><div class="erp-span-2"><label>Interne Notiz</label><textarea name="notes" rows="3"></textarea></div></div><button class="button primary">Zeit speichern</button></form>
<div class="erp-table"><table><thead><tr><th>Datum</th><th>Mitarbeiter</th><th>Erfasst von</th><th>Projekt</th><th>Beginn–Ende</th><th>Pause</th><th>Stunden</th><th>Tätigkeit</th><th>Rapport</th><th></th></tr></thead><tbody><?php foreach($_['rows'] as $r): ?><tr><td><?php p(date('d.m.Y',strtotime($r['work_date']))); ?></td><td><?php p($r['user_id']); ?></td><td><?php p($r['entered_by']??$r['user_id']); ?></td><td><?php p(($r['project_no']??'').' · '.($r['title']??'')); ?></td><td><?php p(trim(($r['start_time']??'').'–'.($r['end_time']??''),'–')); ?></td><td><?php p((string)($r['break_minutes']??0).' Min.'); ?></td><td><strong><?php p(number_format((float)($r['hours']??0),2,',','.')); ?></strong></td><td class="erp-activity"><?php p($r['activity']??''); ?></td><td><?php if($r['imported_to_report_id']): ?><span class="erp-badge">Übernommen</span><?php else: ?><span class="erp-muted">offen</span><?php endif; ?></td><td><?php if(!$r['imported_to_report_id']): ?><form method="post" action="<?php p($url->linkToRoute('reinhardterp.module.deleteWorkday',['id'=>$r['id']])); ?>" onsubmit="return confirm('Zeiteintrag wirklich löschen?')"><input type="hidden" name="requesttoken" value="<?php p($requestToken); ?>"><button class="button icon-delete" title="Löschen"></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
